validate_item_quantity.definition:
CREATE OR REPLACE FUNCTION public.validate_item_quantity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.quantity < 0 THEN
        RAISE EXCEPTION 'quantity must be non-negative';
    END IF;
    RETURN NEW;
END;
$function$

